persistent_result_loop_scratch.source:
fn main() {
    var result: i64[>..] = [];
    for round in 100 {
        var scratch: i64[>..] = [];
        for i in 10 { scratch.push(round + i); }
        result.push(scratch[0]);
    }
    var sum: i64 = 0;
    for x in result { sum += x; }
    assert(result.len == 100 && sum == 4950);
}

result_destination_and_callee_scratch.source:
fn make() -> i64[>..] {
    var scratch: i64[>..] = [];
    for i in 10 { scratch.push(i); }
    return [scratch.len];
}
fn main() {
    var result: i64[>..] = make();
    assert(result[0] == 10);
}

clear_after_reference_last_use.source:
fn main() {
    var xs: i64[>..] = [7];
    let first .= xs[0];
    assert(first == 7);
    xs.clear();
    assert(xs.len == 0);
}

escaping_view.source:
fn main() {
    var outer: u8[>..] = [];
    var view = outer[..];
    { var inner: u8[>..] = [1, 2]; view = inner[..]; }
    print(view.len);
}

